const r = $input.first().json;
const tasa = r.rates?.DOP;
if (r.result !== 'success' || typeof tasa !== 'number') {
  throw new Error('La API no devolvio una tasa DOP valida');
}

// el static data solo se guarda cuando el flujo corre activado, no en pruebas manuales
const memoria = $getWorkflowStaticData('global');
const historial = memoria.historial ?? [];
const anterior = historial.length ? historial[historial.length - 1].tasa : null;

const fecha = new Date().toISOString().slice(0, 10);
historial.push({ fecha, tasa });
memoria.historial = historial.slice(-30);

const cambio = anterior === null ? null : Number((tasa - anterior).toFixed(4));
const tasas = memoria.historial.map((h) => h.tasa);
const promedio = tasas.reduce((a, b) => a + b, 0) / tasas.length;

let texto = `Tasa USD a DOP del ${fecha}: ${tasa.toFixed(2)}.`;
if (cambio !== null) {
  const sentido = cambio > 0 ? 'subio' : cambio < 0 ? 'bajo' : 'se mantuvo';
  texto += ` Respecto a la corrida anterior ${sentido}${cambio === 0 ? '' : ' ' + Math.abs(cambio).toFixed(2)}.`;
}
if (tasas.length > 1) {
  texto += ` Promedio de las ultimas ${tasas.length} corridas: ${promedio.toFixed(2)}.`;
}

return [{ json: { fecha, tasa, anterior, cambio, promedio: Number(promedio.toFixed(4)), corridas: tasas.length, texto } }];
